def is_typealiastype(obj: Any) -> bool:
    try:
        from typing import TypeAliasType
    except ImportError:
        try:
            from typing_extensions import TypeAliasType
        except ImportError:
            return False

    # For Python 3.10, parameterized PEP 695 type aliases are instances of `types.GenericAlias` 
    # in typing_extensions>=4.13.0.
    # On Python 3.10, with `Alias[int]` being such an instance of `GenericAlias`,
    # `isinstance(Alias[int], TypeAliasType)` returns `True`.
    # See https://github.com/python/cpython/issues/89828.
    import sys
    import types
    if sys.version_info[:2] == (3, 10):
        if isinstance(obj, types.GenericAlias):
            return False

    return isinstance(obj, TypeAliasType)
